18	/**
19	 * Formats a schema issue path into the field notation shown in validation errors.
20	 *
21	 * Examples:
22	 * - `['foo']` -> `foo`
23	 * - `['items', 0, 'id']` -> `items[0].id`
24	 */
25	function formatIssuePath(path?: readonly (PropertyKey | StandardSchemaV1.PathSegment)[]): string {
26	  if (!path?.length) {
27	    return '';
28	  }
29	
30	  return path
31	    .map((segment) => {
32	      const key =
33	        typeof segment === 'object' && segment !== null && 'key' in segment ? segment.key : segment;
34	
35	      return typeof key === 'number' ? `[${key}]` : `.${String(key)}`;
36	    })
37	    .join('')
38	    .replace(/^\./, '');
39	}
