41	/**
42	 * Converts schema issues into the newline-separated detail block appended to user-facing errors.
43	 */
44	export function formatIssues(issues: ReadonlyArray<StandardSchemaV1.Issue>): string {
45	  return issues
46	    .map((issue) => {
47	      const path = formatIssuePath(issue.path);
48	      return path === '' ? issue.message : `${path}: ${issue.message}`;
49	    })
