59	/** Generic Standard Schema constraint used across open-service definitions. */
60	export type AnySchema = StandardSchemaV1<unknown, unknown>;
61	
62	/** Convenience alias for declaring Standard Schema compatible input/output contracts. */
63	export type Schema<TInput = unknown, TOutput = TInput> = StandardSchemaV1<TInput, TOutput>;
64	
65	/** Raw caller-facing value type accepted by a schema-backed operation. */
66	export type InferSchemaInput<TSchema extends AnySchema> = StandardSchemaV1.InferInput<TSchema>;
67	
68	/** Parsed value type produced by a schema after validation. */
69	export type InferSchemaOutput<TSchema extends AnySchema> = StandardSchemaV1.InferOutput<TSchema>;
70	
71	/**
72	 * Named schema maps are the core inference surface for inline open-service authoring.
73	 *
74	 * `defineService()` infers one input-schema map and one output-schema map per operation family
75	 * (queries and commands). Keeping those maps separate gives TypeScript a place to correlate the
76	 * `input` and `output` properties of each inline object before it contextually types sibling
77	 * callbacks like `handler`, `preload`, and `static.path`.
78	 */
79	export type OperationInputSchemas = Record<string, AnySchema>;
80	
81	/**
82	 * Output-schema maps must stay key-aligned with their input-schema map.
83	 *
84	 * The authoring helper uses this alias instead of a plain `Record<string, AnySchema>` so each
85	 * operation key retains its own input/output schema pair during inference.
86	 */
87	export type MatchingOutputSchemas<TInputSchemas extends OperationInputSchemas> = {
88	  [TKey in keyof TInputSchemas]: AnySchema;
89	};
90	
91	/**
92	 * Internal utility used to keep handler maps assignable without collapsing everything to `unknown`.
93	 */
94	type BivariantCallback<TArgs extends unknown[], TResult> = {
95	  bivarianceHack(...args: TArgs): TResult;
96	}['bivarianceHack'];
97	
98	/** Runtime shape shared by all command collections after they are built. */
99	export type Command = Record<string, (input: unknown) => Promise<unknown>>;
100	
101	/**
102	 * Runtime command map derived directly from the inferred command schema maps.
103	 *
104	 * Queries only need command-call typing, not the full command definition objects, so this helper
105	 * keeps query contexts readable while still preserving exact input/output types per command.
106	 */
107	export type CommandFunctions<
108	  TCommandInputSchemas extends OperationInputSchemas,
109	  TCommandOutputSchemas extends MatchingOutputSchemas<TCommandInputSchemas>,
110	> = {
111	  [TKey in keyof TCommandInputSchemas]: BivariantCallback<
112	    [input: InferSchemaInput<TCommandInputSchemas[TKey]>],
113	    Promise<InferSchemaOutput<TCommandOutputSchemas[TKey]>>
114	  >;
115	};
