118	 * Public runtime shape of a query.
119	 *
120	 * Queries are always async and can also be subscribed to for reactive updates.
121	 */
122	export type Query<TInput, TOutput> = {
123	  (input: TInput): Promise<TOutput>;
124	  subscribe(input: TInput, callback: (value: TOutput) => void): () => void;
125	};
