 */
export type ServiceHandlerOverrides<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  queries?: Partial<{ [TKey in keyof TQueries]: TQueries[TKey]['handler'] }>;
  commands?: Partial<{ [TKey in keyof TCommands]: TCommands[TKey]['handler'] }>;
};

/** Loosely typed override shape used while applying overrides to a stored definition. */
type LooseHandlerOverrides = {
  queries?: Record<string, AnyQueryDefinition<unknown>['handler']>;
  commands?: Record<string, AnyCommandDefinition<unknown>['handler']>;
};

